import subprocess, json
def export_one(tag_line, extra_fns=""):
    content = f"{tag_line}\n{extra_fns}\nmain() {{ :; }}\n_choice_fn() {{ echo hi; }}\n_default_fn() {{ echo hi; }}\neval \"$(argc --argc-eval \"$0\" \"$@\")\"\n"
    open("/tmp/probe/one.sh","w").write(content)
    out = subprocess.run(["/workspace/executable","--argc-export","/tmp/probe/one.sh"], capture_output=True, text=True)
    if out.returncode!=0:
        return f"ERROR: {out.stdout}{out.stderr}"
    d=json.loads(out.stdout)
    opts=[o for o in d['flag_options'] if o['id'] not in ('help','version')]
    if opts:
        return json.dumps(opts[0], indent=2)
    if d['positionals']:
        return json.dumps(d['positionals'][0], indent=2)
    if d['envs']:
        return json.dumps(d['envs'][0], indent=2)
    return json.dumps(d, indent=2)

tests=[
"# @option -X-*[`_choice_fn`]",
"# @option +X-*[`_choice_fn`]",
"# @option -f --follow:[a|b]",
"# @flag +fa",
"# @option +a -a",
"# @option -b +b",
"# @option +c --c",
"# @flag -fa",
"# @option -oa",
"# @option -o --od <FILE> <FILE>",
"# @option --ca[x|y|z]",
"# @option -s -soa",
]
for t in tests:
    print(f"=== {t} ===")
    print(export_one(t))
    print()
PY"}

