def parse_choice_inner(s, line_no, funcs):
    if s.startswith("="):
        rest=s[1:]
        vals=rest.split("|") if rest else []
        if not vals: return None,None
        return {"type":"Value","value":vals[0]}, {"type":"Values","data":vals}
    elif s.startswith("?`") and s.endswith("`"):
        fn=s[2:-1]
        if fn not in funcs: raise ParseError(f"{fn}(line {line_no}) is missing")
        return None, {"type":"Fn","data":[fn,False]}
    elif s.startswith("`") and s.endswith("`"):
        fn=s[1:-1]
        if fn not in funcs: raise ParseError(f"{fn}(line {line_no}) is missing")
        return None, {"type":"Fn","data":[fn,True]}
    else:
        vals=s.split("|") if s else []
        return None, {"type":"Values","data":vals}
