    if s.startswith("`") and s.endswith("`"):
        fn=s[1:-1]
        if fn not in funcs: raise ParseError(f"{fn}(line {line_no}) is missing")
        return {"type":"Fn","value":fn}
    else:
        return {"type":"Value","value":s}
