    # notations: list of strings like "FILE", "FILE+", "VALUE*", "VALUE?", "CMD"
    # Returns (min,max)
    mn=0;mx=0;has_inf=False
    for n in notations:
        if n.endswith("*"):
            # 0..inf
            mn+=0;has_inf=True
        elif n.endswith("+"):
